  // Validate the full schema again in JavaScript, including offline/mocked responses.
  const schema={"type": "object", "properties": {"report_id": {"type": ["string", "null"]}, "period_start": {"type": ["string", "null"]}, "period_end": {"type": ["string", "null"]}, "currency": {"type": ["string", "null"]}, "products": {"type": "array", "items": {"type": "object", "properties": {"sku": {"type": "string"}, "name": {"type": "string"}, "landed_unit_cost": {"type": ["number", "null"]}, "amazon_fee_per_sold_unit": {"type": ["number", "null"]}, "available_stock": {"type": ["integer", "null"]}, "stock_as_of": {"type": ["string", "null"]}, "weekly": {"type": "object", "properties": {"units": {"type": ["integer", "null"]}, "revenue": {"type": ["number", "null"]}, "ad_spend": {"type": ["number", "null"]}, "ad_sales": {"type": ["number", "null"]}, "refund_amount": {"type": ["number", "null"]}, "return_requests": {"type": ["integer", "null"]}}, "required": ["units", "revenue", "ad_spend", "ad_sales", "refund_amount", "return_requests"], "additionalProperties": false}, "daily": {"type": "array", "items": {"type": "object", "properties": {"date": {"type": "string"}, "units": {"type": ["integer", "null"]}, "revenue": {"type": ["number", "null"]}, "ad_spend": {"type": ["number", "null"]}}, "required": ["date", "units", "revenue", "ad_spend"], "additionalProperties": false}}, "supply": {"type": "object", "properties": {"production_days": {"type": ["integer", "null"]}, "transit_days": {"type": ["integer", "null"]}, "receiving_days": {"type": ["integer", "null"]}, "safety_days": {"type": ["integer", "null"]}, "planned_order_qty": {"type": ["integer", "null"]}, "incoming_qty": {"type": ["integer", "null"]}, "incoming_sellable_date": {"type": ["string", "null"]}}, "required": ["production_days", "transit_days", "receiving_days", "safety_days", "planned_order_qty", "incoming_qty", "incoming_sellable_date"], "additionalProperties": false}, "source_excerpt": {"type": "string"}}, "required": ["sku", "name", "landed_unit_cost", "amazon_fee_per_sold_unit", "available_stock", "stock_as_of", "weekly", "daily", "supply", "source_excerpt"], "additionalProperties": false}}, "period_expenses": {"type": "array", "items": {"type": "object", "properties": {"name": {"type": "string"}, "amount": {"type": ["number", "null"]}, "date": {"type": ["string", "null"]}}, "required": ["name", "amount", "date"], "additionalProperties": false}}, "events": {"type": "array", "items": {"type": "object", "properties": {"id": {"type": "string"}, "date": {"type": ["string", "null"]}, "sku": {"type": ["string", "null"]}, "kind": {"type": "string", "enum": ["return_request", "supplier_delay", "account_action", "newsletter", "review", "other"]}, "summary": {"type": "string"}, "evidence": {"type": "string"}, "deadline": {"type": ["string", "null"]}, "rating": {"type": ["number", "null"]}}, "required": ["id", "date", "sku", "kind", "summary", "evidence", "deadline", "rating"], "additionalProperties": false}}, "missing_information": {"type": "array", "items": {"type": "string"}}}, "required": ["report_id", "period_start", "period_end", "currency", "products", "period_expenses", "events", "missing_information"], "additionalProperties": false};
  function visit(value, schema, path) {
